import{_ as n,o as t,c as r,ah as s}from"./chunks/framework.Bja9t6Wf.js";const g=JSON.parse('{"title":"Drehbuch-Update: Szene 15 - Das Protokoll des Schweigens","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/szene-das-protokoll-des-schweigens.md","filePath":"logbuch/szene-das-protokoll-des-schweigens.md"}'),i={name:"logbuch/szene-das-protokoll-des-schweigens.md"};function a(o,e,h,d,l,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="drehbuch-update-szene-15-das-protokoll-des-schweigens" tabindex="-1">Drehbuch-Update: Szene 15 - Das Protokoll des Schweigens <a class="header-anchor" href="#drehbuch-update-szene-15-das-protokoll-des-schweigens" aria-label="Permalink to &quot;Drehbuch-Update: Szene 15 - Das Protokoll des Schweigens&quot;">​</a></h1><p><strong>STIL:</strong> Kalt, fast klinisch. Hohe Kontraste. Der Raum wirkt steril, trotz der schweren Eichenmöbel. Man hört nur das Ticken einer Wanduhr und das Kratzen einer Feder auf Papier.</p><p><strong>BESETZUNG:</strong></p><ul><li><strong>Helmut Horten:</strong> August Diehl (jung, extrem beherrscht, fast unbeweglich)</li><li><strong>Siegfried Alsberg:</strong> Ein älterer Schauspieler, der Würde ausstrahlt, aber von Erschöpfung und Angst gezeichnet ist.</li></ul><hr><p><strong>INT. ALSBERGS BÜRO - TAG (1933)</strong></p><p>Siegfried Alsberg steht am Fenster und blickt auf die Straße hinunter. Man hört von draußen dumpf Marschmusik und Rufe. Helmut Horten (Diehl) sitzt am Schreibtisch – <em>seinem</em> neuen Schreibtisch. Er blättert in einem Stapel Dokumente.</p><p><strong>ALSBERG</strong> (ohne sich umzudrehen) Mein Vater hat dieses Haus gebaut. Er kannte jeden Stein, jeden Angestellten beim Namen. Wissen Sie, was das bedeutet, Herr Horten?</p><p>Horten antwortet nicht sofort. Er legt ein Dokument beiseite und streicht es mit dem Handrücken glatt.</p><p><strong>HORTEN</strong> (ruhig) Es bedeutet, dass Sie emotional an einem Objekt hängen, das der Markt bereits aufgegeben hat. Steine haben kein Gedächtnis, Herr Alsberg. Und Namen... Namen lassen sich in Lohnlisten sehr leicht ersetzen.</p><p>Alsberg dreht sich langsam um. Seine Hände zittern leicht.</p><p><strong>ALSBERG</strong> Der Preis, den Sie anbieten... das ist kein Preis. Das ist eine Beleidigung. Es deckt nicht einmal die Kredite, die Ihre Freunde bei der Bank plötzlich fällig gestellt haben.</p><p><strong>HORTEN</strong> (sieht ihn direkt an, sein Blick ist leer) Ich mache die Preise nicht, ich lese sie nur ab. Die Situation da draußen... (er deutet vage zum Fenster) ...ist der Preis. Ich biete Ihnen eine Lösung an. Eine saubere Trennung. Sie unterschreiben hier, und Sie können gehen. Ohne Lärm. Ohne... Komplikationen.</p><p><strong>ALSBERG</strong> (bitter) &quot;Marktbereinigung&quot;. Das ist Ihr Wort dafür, nicht wahr?</p><p><strong>HORTEN</strong> Es ist ein technischer Begriff. Effizienz ist nicht grausam, Herr Alsberg. Sie ist nur konsequent. Das Universum bevorzugt Vakuum, und im deutschen Handel gibt es gerade sehr viel davon. Ich fülle es lediglich.</p><p>Horten schiebt den Füllfederhalter über den Schreibtisch. Er glänzt im fahlen Licht.</p><p><strong>HORTEN</strong> Unterschreiben Sie das Protokoll. Es ist ein Akt der Vernunft. Für Sie ist es das Ende einer Ära. Für mich... ist es der erste Quadratmeter.</p><p>Alsberg starrt den Stift an, als wäre er eine Waffe. Das Ticken der Uhr wird lauter.</p><p><strong>FADE TO BLACK.</strong></p>',19)])])}const p=n(i,[["render",a]]);export{g as __pageData,p as default};
